function fail(message) {
  console.error(`prototype-mocks: ${message}`);
  process.exit(1);
}

function readJson(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (error) {
    fail(`${path.relative(process.cwd(), filePath)} is not valid JSON: ${error.message}`);
  }
}

function readOptional(filePath) {
  return fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : '';
}

function loadExperienceContract(projectDir) {
  const contractPath = path.join(projectDir, '.tmp', 'experience-contract.json');
  if (!fs.existsSync(contractPath)) return null;
  const contract = readJson(contractPath);
  if (contract.schemaVersion !== 1 || !contract.entryMode || !contract.primaryJob) {
    fail('.tmp/experience-contract.json must contain schemaVersion, entryMode, and primaryJob');
  }
  return contract;
}

function loadScreenBuildPack(projectDir) {
  const packPath = path.join(projectDir, '.tmp', 'screen-build-pack.json');
  if (!fs.existsSync(packPath)) return null;
  const pack = readJson(packPath);
  const result = validateScreenBuildPack(projectDir, pack);
  if (result.issues.length) {
    fail(`screen build pack is invalid: ${result.issues.map((issue) => issue.rule).join(', ')}`);
  }
  return pack;
}

function serviceIdentifier(logicalName) {
  const identifier = logicalName.replace(/[^A-Za-z0-9_$]/g, '_');
  return identifier.charAt(0).toUpperCase() + identifier.slice(1);
}

function normalizeType(rawType) {
  const type = String(rawType || 'string').toLowerCase();
  if (['integer', 'bigint', 'decimal', 'double', 'money', 'number', 'int', 'wholenumber', 'whole number'].includes(type)) return 'number';
  if (['boolean', 'bool', 'yes/no'].includes(type)) return 'boolean';
  if (['choice', 'picklist', 'multiselectchoice'].includes(type)) return 'choice';
  if (['datetime', 'date'].includes(type)) return 'date';
  if (type === 'lookup') return 'lookup';
  if (type === 'image') return 'image';
  if (type === 'file') return 'file';
  return 'string';
}

function normalizeContractTable(table) {
  if (!table || !table.logicalName) fail('schema contract contains a table without logicalName');
  const decision = String(table.plannedDecision || table.decision || '').toLowerCase();
  if (decision === 'defer' || table.serviceRequired === false) return null;

  const logicalName = String(table.logicalName);
  const fields = (table.columns || [])
    .filter((column) => String(column.plannedDecision || column.decision || '').toLowerCase() !== 'defer')
    .map((column) => ({
      name: String(column.logicalName || ''),
      displayName: String(column.displayName || column.logicalName || ''),
      type: normalizeType(column.type || column.attributeType),
      rawType: String(column.type || column.attributeType || 'string'),
      required: /required/i.test(String(column.requiredLevel || '')),
      lookupTarget: column.lookupTarget || column.target || null,
      options: Array.isArray(column.options) ? column.options : [],
      primaryName: column.primaryName === true,
      fixtureValues: Array.isArray(column.fixtureValues)
        ? column.fixtureValues
        : Array.isArray(column.sampleValues)
          ? column.sampleValues
          : [],
      fixtureValue: Object.prototype.hasOwnProperty.call(column, 'fixtureValue')
        ? column.fixtureValue
        : column.defaultValue,
    }))
    .filter((column) => column.name);

  return {
    logicalName,
    displayName: String(table.displayName || logicalName),
    serviceName: serviceIdentifier(logicalName),
    primaryKey: String(table.primaryIdAttribute || `${logicalName}id`),
    dependencyTier: Number.isInteger(table.dependencyTier) ? table.dependencyTier : 0,
    fixtureRowCount: Number.isInteger(table.fixtureRowCount) && table.fixtureRowCount >= 0
      ? table.fixtureRowCount
      : Number.isInteger(table.prototypeRowCount) && table.prototypeRowCount >= 0
        ? table.prototypeRowCount
        : null,
    fields,
  };
}

function parseLegacyEntities(markdown) {
  const entities = [];
  const blockPattern = /\*\*([A-Z][\w\s]+?)\*\*\s*\(`([a-z][a-z0-9_]+)`\)[^\n]*\n((?:\s*-\s*`[^`]+`[^\n]*\n?)+)/g;
  let match;
  while ((match = blockPattern.exec(markdown)) !== null) {
    const logicalName = match[2];
    const fields = [];
    for (const line of match[3].split('\n')) {
      const fieldMatch = line.match(/-\s*`([^`]+)`\s*\(([^)]+)\)/);
      if (!fieldMatch) continue;
      const rawType = fieldMatch[2];
      const lookupMatch = rawType.match(/lookup\s*(?:to|->|:)?\s*`?([a-z][a-z0-9_]*)/i);
      fields.push({
        name: fieldMatch[1],
        displayName: fieldMatch[1],
        type: normalizeType(rawType.split(/[,(]/)[0].trim()),
        rawType,
        required: !/nullable|optional/i.test(rawType),
        lookupTarget: lookupMatch ? lookupMatch[1].toLowerCase() : null,
        options: [],
        primaryName: /(^|_)name$/.test(fieldMatch[1]),
      });
    }
    if (fields.length) {
      entities.push({
        logicalName,
        displayName: match[1].trim(),
        serviceName: serviceIdentifier(logicalName),
        primaryKey: `${logicalName}id`,
        fields,
      });
    }
  }
  return entities;
}

function loadEntities(projectDir, planText) {
  const contractPath = path.join(projectDir, '.tmp', 'dataverse-schema-contract.json');
  if (fs.existsSync(contractPath)) {
    const contract = readJson(contractPath);
    if (!Array.isArray(contract.tables)) fail('schema contract must contain a tables array');
    const entities = contract.tables.map(normalizeContractTable).filter(Boolean);
    if (!entities.length) fail('schema contract contains no service-required tables');
    return { entities, source: '.tmp/dataverse-schema-contract.json' };
  }

  const entities = parseLegacyEntities(planText);
  if (!entities.length) {
    fail('no entities found; create .tmp/dataverse-schema-contract.json during planning or use the legacy entity-block format');
  }
  return { entities, source: 'native-app-plan.md (legacy fallback)' };
}

function connectorServiceName(apiName) {
  if (CONNECTOR_SERVICE_NAMES[apiName]) return CONNECTOR_SERVICE_NAMES[apiName];
  return apiName
    .replace(/[^a-z0-9]+/gi, ' ')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1).toLowerCase())
    .join('');
}

function parseConnectors(markdown) {
  const heading = /^##\s+Connectors\s*\n/m.exec(markdown);
  if (!heading) return [];
  const remainder = markdown.slice(heading.index + heading[0].length);
  const nextHeading = remainder.search(/^##\s+/m);
  const body = nextHeading >= 0 ? remainder.slice(0, nextHeading) : remainder;
  if (/^\s*[_*]?none[_*]?\s*(?:-|$)/im.test(body)) return [];

  const connectors = [];
  const rowPattern = /^\|\s*([^|]+?)\s*\|\s*`([a-z0-9_-]+)`\s*\|\s*([^|]+?)\s*\|\s*[^|]+\|\s*$/gim;
  let match;
  while ((match = rowPattern.exec(body)) !== null) {
    if (/^connector$/i.test(match[1].trim())) continue;
    connectors.push({
      displayName: match[1].trim(),
      apiName: match[2].trim(),
      purpose: match[3].trim(),
      serviceName: connectorServiceName(match[2].trim()),
    });
  }
  return connectors;
}

function connectorsFromExecutionContract(projectDir) {
  const contractPath = path.join(projectDir, '.tmp', 'mobile-plan-execution-contract.json');
  if (!fs.existsSync(contractPath)) return null;
  const contract = readJson(contractPath);
  if (!Array.isArray(contract.connectorOperations)) fail('execution contract connectorOperations must be an array');
  const grouped = new Map();
  for (const operation of contract.connectorOperations) {
    if (!operation?.apiName || !operation?.service || !operation?.operation) fail('execution contract connector operation requires apiName, service, and operation');
    if (!/^[A-Za-z_$][A-Za-z0-9_$]*Service$/.test(operation.service) || !/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(operation.operation)) {
      fail(`execution contract connector operation has unsafe TypeScript identifiers: ${operation.service}.${operation.operation}`);
    }
    const existing = grouped.get(operation.service) || {
      displayName: String(operation.connector || operation.apiName),
      apiName: String(operation.apiName),
      purpose: `Provide ${operation.connector || operation.apiName} operations required by the approved screens`,
      serviceName: operation.service.replace(/Service$/, ''),
      operations: [],
    };
    if (existing.apiName !== operation.apiName) fail(`connector service ${operation.service} maps to multiple API names`);
    existing.operations.push(String(operation.operation));
    grouped.set(operation.service, existing);
  }
  return [...grouped.values()].map((connector) => ({
    ...connector,
    operations: [...new Set(connector.operations)].sort(),
  }));
}

function domainPack(contextText) {
  const lower = contextText.toLowerCase();
  return Object.values(DOMAIN_PACKS).find((pack) => pack.match.test(lower)) || DOMAIN_PACKS.generic;
}

function titleCase(value) {
  return String(value || '')
    .trim()
    .replace(/\s+/g, ' ')
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function uniqueStrings(values) {
  const seen = new Set();
  return values.filter((value) => {
    const key = String(value || '').trim().toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function evidenceTerms(contract, signal) {
  const spans = Array.isArray(contract?.promptEvidence?.contentModel)
    ? contract.promptEvidence.contentModel
    : Object.values(contract?.promptEvidence || {}).flat();
  return uniqueStrings(spans
    .filter((span) => span?.signal === signal && typeof span.text === 'string')
    .map((span) => titleCase(span.text)));
}

function experiencePack(contract) {
  const copy = EXPERIENCE_COPY[contract.entryMode] || EXPERIENCE_COPY.onboarding;
  const subject = Array.isArray(contract.contentModel) && contract.contentModel.length
    ? contract.contentModel[0]
    : 'item';
  const audiencePeople = contract.audience === 'employee'
    ? ['Alex Morgan', 'Jordan Lee', 'Casey Rivera', 'Taylor Brooks']
    : contract.audience === 'consumer'
      ? ['Alex Morgan', 'Jamie Rivera', 'Sam Lee', 'Taylor Quinn']
      : ['Alex Morgan', 'Jordan Lee', 'Casey Rivera', 'Taylor Quinn'];
  const subjectLocations = subject === 'locations'
    ? ['Nearby', 'Saved place', 'Current location', 'Recommended place']
    : subject === 'products'
      ? ['For you', 'Popular now', 'Saved collection', 'Nearby']
      : ['Today', 'This week', 'Saved context', 'Recent activity'];
  const primaryJob = String(contract.primaryJob).replace(/[.]+$/, '');
  const evidenceText = Object.values(contract.promptEvidence || {})
    .flat()
    .map((span) => span?.text || '')
    .join(' ')
    .toLowerCase();
  const warehouseWorkflow = contract.audience === 'employee'
    && contract.primarySurface === 'task-led-workflow'
    && /\b(?:warehouse|bins?|cycle count|receiving)\b/.test(evidenceText);
  if (contract.primarySurface === 'product-led-discovery') {
    const evidenceCategories = evidenceTerms(contract, 'category')
      .filter((value) => !/^(?:inventory|items?|products?|media|categor(?:y|ies)|collections?)$/i.test(value));
    const categories = evidenceCategories.length
      ? evidenceCategories
      : ['Essentials', 'New arrivals', 'Popular picks', 'Gift ideas'];
    const modifiers = ['Featured', 'Everyday', 'Premium', 'New', 'Popular', 'Essential', 'Signature', 'Selected'];
    const titles = evidenceCategories.length
      ? modifiers.map((modifier, index) => `${modifier} ${categories[index % categories.length].toLowerCase()}`)
      : ['Featured essential', 'New arrival', 'Popular choice', 'Gift-ready pick', 'Everyday favorite', 'Premium option', 'Selected item', 'Saved choice'];
    return {
      titles,
      people: audiencePeople,
      locations: ['Featured collection', ...categories.slice(0, 3).map((category) => `${category} collection`)],
      categories,
      notes: ['Available to choose', 'Prepared for easy browsing', 'Details remain available offline', 'A useful option to compare'],
      statuses: ['Available', 'Featured', 'Popular', 'Limited'],
      priorities: ['Featured', 'Recommended', 'Popular', 'Saved'],
      primaryJob,
    };
  }
  if (warehouseWorkflow) {
    return {
      titles: ['Bin A-14 cycle count', 'Receiving Dock 3 scan', 'Aisle 7 recount', 'Returns hold review', 'Transfer verification', 'Damaged goods check', 'Low-stock bin review', 'Cycle-count assignment'],
      people: audiencePeople,
      locations: ['Bin A-14', 'Receiving Dock 3', 'Aisle 7 Bay 2', 'Returns Hold'],
      categories: ['Cycle count', 'Receiving', 'Transfer', 'Variance'],
      notes: ['Scan the bin before confirming', 'Variance needs a recount', 'Assignment is ready to continue', 'Record the receiving status'],
      statuses: ['Assigned', 'Scanning', 'Needs recount', 'Complete'],
      priorities: ['Urgent', 'High', 'Normal', 'Low'],
      primaryJob,
    };
  }
  return {
    titles: copy.titles.map((title, index) => index === 0 ? `${title}: ${primaryJob}` : `${title} ${index + 1}`),
    people: audiencePeople,
    locations: subjectLocations,
    categories: copy.categories,
    notes: copy.notes,
    statuses: ['Draft', 'In progress', 'Blocked', 'Needs review', 'Complete', 'Overdue', 'Approved', 'Archived'],
    priorities: ['Critical', 'High', 'Medium', 'Low'],
    primaryJob,
  };
}

function deterministicGuid(seed) {
  const hex = crypto.createHash('sha256').update(seed).digest('hex').slice(0, 32);
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function dateValue(index, fieldName) {
  const offsets = /created|modified|completed|closed|submitted/i.test(fieldName)
    ? [-30, -14, -7, -3, -1, 0, -21, -5]
    : [-7, -1, 0, 1, 3, 7, 14, 30];
  const value = new Date('2026-01-15T09:00:00.000Z');
  value.setUTCDate(value.getUTCDate() + offsets[index % offsets.length]);
  return value.toISOString();
}

function resolveLookupTarget(field, entities) {
  if (field.lookupTarget) {
    const target = String(field.lookupTarget).toLowerCase();
    const exact = entities.find((entity) => entity.logicalName.toLowerCase() === target);
    if (exact) return exact;
  }
  const compact = field.name.toLowerCase().replace(/^_/, '').replace(/_value$/, '').replace(/id$/, '').replace(/_/g, '');
  return entities.find((entity) => {
    const logical = entity.logicalName.toLowerCase().replace(/_/g, '');
    return compact === logical || compact.endsWith(logical) || logical.endsWith(compact);
  }) || null;
}

function semanticKey(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function slugValue(value) {
  return semanticKey(value).replace(/\s+/g, '-');
}

function entityAliases(entity) {
  const logicalParts = String(entity.logicalName).split('_');
  return uniqueStrings([
    entity.displayName,
    entity.logicalName,
    logicalParts.length > 1 ? logicalParts.slice(1).join(' ') : entity.logicalName,
  ]).map(semanticKey);
}

function fixtureScenarioInputs(screenBuildPack) {
  const inputs = [];
  const canonicalStates = new Set(['populated', 'loading', 'empty', 'error', 'offline', 'unavailable', 'media-fallback']);
  for (const screen of screenBuildPack?.screens || []) {
    for (const state of screen.states || []) {
      const normalizedState = String(state).toLowerCase();
      inputs.push({ screenId: screen.id, description: String(state), state: canonicalStates.has(normalizedState) ? normalizedState : null });
    }
    for (const scenario of screen.data?.fixtureScenarios || []) {
      if (typeof scenario === 'string') {
        inputs.push({ screenId: screen.id, description: scenario, state: null });
      } else if (scenario && typeof scenario === 'object') {
        inputs.push({
          screenId: screen.id,
          description: String(scenario.description || scenario.label || scenario.id || scenario.state || 'populated'),
          state: scenario.state ? String(scenario.state).toLowerCase() : null,
          rowCounts: scenario.rowCounts && typeof scenario.rowCounts === 'object' ? scenario.rowCounts : null,
        });
      }
    }
  }
  return inputs;
}

function fixtureScenarioState(input) {
  if (input.state) return input.state;
  const description = input.description.toLowerCase();
  if (/media[^.]*fallback|fallback[^.]*media|image[^.]*fallback|missing media|code-native illustration/.test(description)) return 'media-fallback';
  if (/\bunavailable\b|out[ -]of[ -]stock|cannot be (?:added|selected|chosen)/.test(description)) return 'unavailable';
  if (/\bempty\b|\bno (?:items|products|records|results)\b|unknown .* renders? .*empty/.test(description)) return 'empty';
  if (/\boffline\b/.test(description)) return 'offline';
  if (/\bloading\b/.test(description)) return 'loading';
  if (/\berror\b|\bfailure\b/.test(description)) return 'error';
  return 'populated';
}

function categoricalTargets(entities) {
  const targets = new Set();
  for (const entity of entities) {
    for (const field of entity.fields) {
      if (field.type !== 'lookup' || !/category|type|segment|collection|group/i.test(`${field.name} ${field.displayName}`)) continue;
      const target = resolveLookupTarget(field, entities);
      if (target) targets.add(target.logicalName);
    }
  }
  return targets;
}

function buildFixturePolicy(entities, screenBuildPack, pack) {
  const inputs = fixtureScenarioInputs(screenBuildPack);
  const requestedStates = new Set(inputs.map(fixtureScenarioState));
  const configuredRowCounts = screenBuildPack?.fixtures?.rowCounts || {};
  const explicitRowCounts = new Map();
  for (const [key, value] of Object.entries(configuredRowCounts)) {
    if (Number.isInteger(value) && value >= 0) explicitRowCounts.set(semanticKey(key), value);
  }
  for (const input of inputs) {
    for (const [key, value] of Object.entries(input.rowCounts || {})) {
      if (Number.isInteger(value) && value >= 0) explicitRowCounts.set(semanticKey(key), value);
    }
  }
  const singletonEntities = new Set();
  for (const input of inputs.filter((candidate) => /\bsingleton\b/i.test(candidate.description))) {
    const description = semanticKey(input.description);
    for (const entity of entities) {
      if (entityAliases(entity).some((alias) => alias && description.includes(alias))) {
        singletonEntities.add(entity.logicalName);
      }
    }
  }
  const defaults = {
    currencyCode: String(screenBuildPack?.fixtures?.defaults?.currencyCode || 'USD').toUpperCase(),
  };
  const categories = categoricalTargets(entities);
  return {
    inputs,
    requestedStates,
    explicitRowCounts,
    singletonEntities,
    categoricalTargets: categories,
    defaults,
    rowCount(entity) {
      if (entity.fixtureRowCount !== null && entity.fixtureRowCount !== undefined) return entity.fixtureRowCount;
      for (const alias of entityAliases(entity)) {
        if (explicitRowCounts.has(alias)) return explicitRowCounts.get(alias);
      }
      if (singletonEntities.has(entity.logicalName)) return 1;
      if (categories.has(entity.logicalName)) return Math.max(1, uniqueStrings(pack.categories).length);
      const semanticName = `${entity.logicalName} ${entity.displayName}`.toLowerCase();
      if (/(?:cart|basket|order|selection|saved|favorite)[ _-]?(?:line|item)$|(?:line|selection)[ _-]?item$/.test(semanticName)) return 3;
      return 8;
    },
  };
}

function configuredFixtureValue(field, index) {
  if (field.fixtureValues?.length) return field.fixtureValues[index % field.fixtureValues.length];
  if (field.fixtureValue !== undefined) return field.fixtureValue;
  return undefined;
}

function primarySemanticValue(entity, semanticIndex, pack, fixturePolicy) {
  if (fixturePolicy.categoricalTargets.has(entity.logicalName)) {
    return pack.categories[semanticIndex % pack.categories.length];
  }
  if (fixturePolicy.singletonEntities.has(entity.logicalName)) return entity.displayName;
  return pack.titles[semanticIndex % pack.titles.length];
}

function textValue(field, entity, index, semanticIndex, pack, fixturePolicy) {
  const name = field.name.toLowerCase();
  const primaryValue = primarySemanticValue(entity, semanticIndex, pack, fixturePolicy);
  if (field.primaryName || /(^|_)(name|title|subject)$/.test(name)) return primaryValue;
  if (/slug/.test(name)) return slugValue(primaryValue);
  if (/currency/.test(name)) return fixturePolicy.defaults.currencyCode;
  if (/(^|_)(sku|code|key)$/.test(name) || /(?:sku|code|key)$/.test(name)) {
    const prefix = slugValue(entity.displayName) || slugValue(entity.logicalName) || 'item';
    return `${prefix.toUpperCase()}-${String(index + 1).padStart(3, '0')}`;
  }
  if (/email/.test(name)) return `user${index + 1}@example.com`;
  if (/phone/.test(name)) return `+1-555-01${String(index).padStart(2, '0')}`;
  if (/available|availability|status|state|phase/.test(name)) return pack.statuses[index % pack.statuses.length];
  if (/priority|severity|risk|urgency/.test(name)) return pack.priorities[index % pack.priorities.length];
  if (/person|contact|owner|assignee|patient|technician|user/.test(name)) return pack.people[index % pack.people.length];
  if (/location|site|store|facility|warehouse|bin|address/.test(name)) return pack.locations[index % pack.locations.length];
  if (/category|type|segment/.test(name)) return pack.categories[semanticIndex % pack.categories.length];
  if (/description|notes|summary|comment|reason/.test(name)) return pack.notes[index % pack.notes.length];
  return `${entity.displayName} ${index + 1}`;
}

function primaryNameField(entity) {
  return entity.fields.find((field) => field.primaryName)
    || entity.fields.find((field) => /(^|_)(name|title|subject)$/.test(field.name.toLowerCase()))
    || null;
}

function semanticFieldValue(field, entity, row, index, semanticIndex, pack, fixturePolicy) {
  const existing = row?.[field?.name];
  if (existing !== null && existing !== undefined && existing !== '') return String(existing);
  const configured = configuredFixtureValue(field || {}, index);
  if (configured !== undefined && configured !== null && configured !== '') return String(configured);
  if (field?.primaryName) return primarySemanticValue(entity, semanticIndex, pack, fixturePolicy);
  return '';
}

function mediaSubject(entity, index, semanticIndex, entities, rowsByEntity, pack, fixturePolicy) {
  const linkedCandidates = entity.fields
    .filter((field) => field.type === 'lookup')
    .map((field) => ({ field, target: resolveLookupTarget(field, entities) }))
    .filter(({ target }) => target
      && !fixturePolicy.categoricalTargets.has(target.logicalName)
      && !fixturePolicy.singletonEntities.has(target.logicalName))
    .sort((left, right) => {
      const leftScore = /product|offer|listing|article|content|item/i.test(`${left.field.name} ${left.field.displayName} ${left.target.displayName}`) ? 1 : 0;
      const rightScore = /product|offer|listing|article|content|item/i.test(`${right.field.name} ${right.field.displayName} ${right.target.displayName}`) ? 1 : 0;
      return rightScore - leftScore;
    });
  const linked = linkedCandidates[0];
  const linkedRow = linked ? lookupRow(linked.field, index, linked.target, rowsByEntity, pack, fixturePolicy) : null;
  return linkedRow ? { entity: linked.target, row: linkedRow } : {
    entity,
    row: (rowsByEntity.get(entity.logicalName) || [])[index] || null,
  };
}

function mediaSemanticContext(entity, index, semanticIndex, entities, rowsByEntity, pack, fixturePolicy) {
  const subject = mediaSubject(entity, index, semanticIndex, entities, rowsByEntity, pack, fixturePolicy);
  const nameField = primaryNameField(subject.entity);
  const title = semanticFieldValue(nameField, subject.entity, subject.row, semanticIndex, semanticIndex, pack, fixturePolicy)
    || pack.titles[semanticIndex % pack.titles.length]
    || subject.entity.displayName;
  const categoryField = subject.entity.fields.find((field) => /category|type|segment|collection|group/i.test(`${field.name} ${field.displayName}`));
  let category = '';
  if (categoryField?.type === 'lookup') {
    const target = resolveLookupTarget(categoryField, entities);
    const categoryRow = target ? lookupRow(categoryField, semanticIndex, target, rowsByEntity, pack, fixturePolicy) : null;
    category = target && categoryRow
      ? semanticFieldValue(primaryNameField(target), target, categoryRow, semanticIndex, semanticIndex, pack, fixturePolicy)
      : '';
  } else if (categoryField) {
    category = semanticFieldValue(categoryField, subject.entity, subject.row, semanticIndex, semanticIndex, pack, fixturePolicy);
  }
  if (!category) category = pack.categories[semanticIndex % pack.categories.length] || '';
  const family = semanticMediaFamily(subject.entity.displayName, title, category, pack.primaryJob);
  return { title, category, family };
}

function mediaFixture(entity, index, entities, rowsByEntity, pack, fixturePolicy, semanticIndex = index) {
  const { title, category, family } = mediaSemanticContext(
    entity, index, semanticIndex, entities, rowsByEntity, pack, fixturePolicy,
  );
  return {
    imageUrl: approvedMediaUrl(family, `${family}:${title}:${category}:${entity.logicalName}:${index}`),
    imageAltText: category ? `${title} in ${category}` : `${title} image`,
    imageCacheKey: `experience:${entity.logicalName}:${index + 1}:v1`,
    imageAssetKey: assetKeyFor(entity, index),
  };
}

function lookupRow(field, index, target, rowsByEntity, pack, fixturePolicy) {
  const parentRows = rowsByEntity.get(target.logicalName) || [];
  if (!parentRows.length) return null;
  if (fixturePolicy.categoricalTargets.has(target.logicalName)) {
    const desired = semanticKey(pack.categories[index % pack.categories.length]);
    const primaryName = target.fields.find((candidate) => candidate.primaryName)?.name;
    const match = primaryName
      ? parentRows.find((row) => semanticKey(row[primaryName]) === desired)
      : null;
    if (match) return match;
  }
  return parentRows[index % parentRows.length];
}

function semanticRecordIndex(entity, index, entities, rowsByEntity, fixturePolicy) {
  if (!/media|image|photo|asset|line.?item|cart.?item|selection.?item|saved.?item|favorite/i.test(`${entity.logicalName} ${entity.displayName}`)) {
    return index;
  }
  const candidates = entity.fields
    .filter((field) => field.type === 'lookup')
    .map((field) => ({ field, target: resolveLookupTarget(field, entities) }))
    .filter(({ target }) => target
      && !fixturePolicy.categoricalTargets.has(target.logicalName)
      && !fixturePolicy.singletonEntities.has(target.logicalName))
    .sort((left, right) => {
      const leftScore = /product|offer|listing|article|content|item/i.test(`${left.field.name} ${left.field.displayName} ${left.target.displayName}`) ? 1 : 0;
      const rightScore = /product|offer|listing|article|content|item/i.test(`${right.field.name} ${right.field.displayName} ${right.target.displayName}`) ? 1 : 0;
      return rightScore - leftScore;
    });
  const target = candidates[0]?.target;
  const parentRows = target ? rowsByEntity.get(target.logicalName) || [] : [];
  return parentRows.length ? index % parentRows.length : index;
}

function fieldValue(field, entity, index, entities, rowsByEntity, pack, assetPolicy, fixturePolicy) {
  const target = field.type === 'lookup' ? resolveLookupTarget(field, entities) : null;
  if (target) {
    const parentRow = lookupRow(field, index, target, rowsByEntity, pack, fixturePolicy);
    return parentRow
      ? parentRow[target.primaryKey]
      : deterministicGuid(`${target.logicalName}-${index}`);
  }

  const configuredValue = configuredFixtureValue(field, index);
  if (configuredValue !== undefined) return configuredValue;

  const semanticIndex = semanticRecordIndex(entity, index, entities, rowsByEntity, fixturePolicy);
  const media = mediaFixture(entity, index, entities, rowsByEntity, pack, fixturePolicy, semanticIndex);
  const fieldName = field.name.toLowerCase();
  if (/(?:image|photo|media).*url|url.*(?:image|photo|media)/.test(fieldName)) {
    return ['remote-cdn-cached', 'remote-allowed'].includes(assetPolicy?.media)
      ? media.imageUrl
      : media.imageAssetKey;
  }
  if (/(?:image|photo|media).*(?:alt|description)|(?:alt|description).*(?:image|photo|media)/.test(fieldName)) return media.imageAltText;
  if (/(?:image|photo|media).*(?:cache|key)|(?:cache|key).*(?:image|photo|media)/.test(fieldName)) {
    return /(?:asset|fallback)/.test(fieldName) ? media.imageAssetKey : media.imageCacheKey;
  }

  if (field.type === 'number') {
    if (/amount|total|cost|price|budget|revenue/i.test(field.name)) return [42.5, 128.99, 319.45, 875, 1499.95, 12.75, 64.2, 240][index % 8];
    if (/quantity|qty/i.test(field.name)) return [1, 2, 1, 3, 2, 1, 4, 2][index % 8];
    if (/count|stock|available|variance/i.test(field.name)) return [0, 3, 12, 48, 96, 5, 21, 64][index % 8];
    return index + 1;
  }
  if (field.type === 'boolean') return index % 3 !== 1;
  if (field.type === 'date') return dateValue(index, field.name);
  if (field.type === 'choice' && field.options.length) {
    const option = field.options[index % field.options.length];
    return typeof option === 'object' && option !== null ? option.value : option;
  }
  if (field.type === 'image') {
    return ['remote-cdn-cached', 'remote-allowed'].includes(assetPolicy?.media)
      ? media.imageUrl
      : media.imageAssetKey;
  }
  if (field.type === 'file') {
    return JSON.stringify({ fileName: `${entity.logicalName}-${index + 1}.pdf`, mimeType: 'application/pdf', sizeKb: 128 + index * 32 });
  }
  return textValue(field, entity, index, semanticIndex, pack, fixturePolicy);
}

function generationOrder(entities) {
  const originalIndex = new Map(entities.map((entity, index) => [entity.logicalName, index]));
  const remaining = new Set(entities.map((entity) => entity.logicalName));
  const ordered = [];
  while (remaining.size) {
    const ready = entities
      .filter((entity) => remaining.has(entity.logicalName))
      .filter((entity) => entity.fields.every((field) => {
        if (field.type !== 'lookup') return true;
        const target = resolveLookupTarget(field, entities);
        return !target || !remaining.has(target.logicalName) || target.logicalName === entity.logicalName;
      }))
      .sort((left, right) => left.dependencyTier - right.dependencyTier
        || originalIndex.get(left.logicalName) - originalIndex.get(right.logicalName));
    const next = ready[0] || entities.find((entity) => remaining.has(entity.logicalName));
    ordered.push(next);
    remaining.delete(next.logicalName);
  }
  return ordered;
}

function generateSeeds(entities, contextText, experienceContract, screenBuildPack = null) {
  // A prompt-derived contract describes the actual user job and entry mode;
  // keyword packs only preserve readable seeds for pre-contract prototypes.
  const sourcePack = experienceContract ? experiencePack(experienceContract) : domainPack(contextText);
  const fixturePolicy = buildFixturePolicy(entities, screenBuildPack, sourcePack);
  const pack = fixturePolicy.requestedStates.has('unavailable')
    ? { ...sourcePack, statuses: uniqueStrings([...sourcePack.statuses, 'Unavailable']) }
    : sourcePack;
  const rowsByEntity = new Map();
  for (const entity of entities) {
    const rowCount = fixturePolicy.rowCount(entity);
    rowsByEntity.set(entity.logicalName, Array.from({ length: rowCount }, (_, index) => ({
      [entity.primaryKey]: deterministicGuid(`${entity.logicalName}-${index}`),
    })));
  }

  for (const entity of generationOrder(entities)) {
    const rows = rowsByEntity.get(entity.logicalName);
    for (let index = 0; index < rows.length; index += 1) {
      for (const field of entity.fields) {
        if (field.name === entity.primaryKey) continue;
        rows[index][field.name] = fieldValue(field, entity, index, entities, rowsByEntity, pack, experienceContract?.assetPolicy, fixturePolicy);
      }
    }
  }
  return rowsByEntity;
}

function buildFixtureScenarioManifest(screenBuildPack, entities, rowsByEntity, assetManifest) {
  const inputs = fixtureScenarioInputs(screenBuildPack);
  const states = uniqueStrings(['populated', ...inputs.map(fixtureScenarioState)]);
  const allRecordIds = Object.fromEntries(entities.map((entity) => [
    entity.logicalName,
    (rowsByEntity.get(entity.logicalName) || []).map((row) => row[entity.primaryKey]),
  ]));
  const unavailableCandidate = entities.flatMap((entity) => {
    const field = entity.fields.find((candidate) => /available|availability|inventory|stock/i.test(`${candidate.name} ${candidate.displayName}`));
    if (!field) return [];
    const rows = rowsByEntity.get(entity.logicalName) || [];
    const row = rows.find((candidate) => /unavailable|out[ -]of[ -]stock/i.test(String(candidate[field.name] || '')))
      || rows[rows.length - 1];
    return row ? [{ entity, field, row }] : [];
  })[0] || null;
  const mediaCandidate = Object.entries(assetManifest.media?.records || {})[0] || null;

  const scenarios = states.map((state) => {
    const matchingInputs = inputs.filter((input) => fixtureScenarioState(input) === state);
    const recordOverrides = {};
    if (state === 'unavailable' && unavailableCandidate) {
      const recordKey = `${unavailableCandidate.entity.logicalName}:${unavailableCandidate.row[unavailableCandidate.entity.primaryKey]}`;
      recordOverrides[recordKey] = {
        availability: 'Unavailable',
        sourceField: unavailableCandidate.field.name,
      };
    }
    if (state === 'media-fallback' && mediaCandidate) {
      recordOverrides[mediaCandidate[0]] = {
        imageUrl: null,
        imageAssetKey: mediaCandidate[1].imageAssetKey,
        sourcePriority: 'local',
      };
    }
    return {
      id: state,
      state,
      screenIds: uniqueStrings(matchingInputs.map((input) => input.screenId)),
      descriptions: uniqueStrings(matchingInputs.map((input) => input.description)),
      recordsByEntity: state === 'empty'
        ? Object.fromEntries(entities.map((entity) => [entity.logicalName, []]))
        : allRecordIds,
      recordOverrides,
    };
  });

  return {
    schemaVersion: 1,
    source: screenBuildPack ? '.tmp/screen-build-pack.json#screens[].data.fixtureScenarios' : 'generator-defaults',
    screenBuildPackRevision: screenBuildPack?.revision || null,
    scenarios,
  };
}

function loadPreviousPrototype(projectDir, entities) {
  const manifestPath = path.join(projectDir, 'src', 'generated', '.prototype-manifest.json');
  if (!fs.existsSync(manifestPath)) {
    return { manifest: null, rowsByEntity: new Map(), schemaByEntity: new Map() };
  }

  const manifest = readJson(manifestPath);
  const schemaByEntity = new Map(
    (manifest.tableSchemas || []).map((schema) => [schema.logicalName, schema]),
  );
  const rowsByEntity = new Map();
  for (const entity of entities) {
    const previousSchema = schemaByEntity.get(entity.logicalName);
    const relativeSeedPath = previousSchema?.seedFile
      || `src/generated/services/${entity.serviceName}.seed.json`;
    const seedPath = path.join(projectDir, relativeSeedPath);
    if (!fs.existsSync(seedPath)) continue;
    const rows = readJson(seedPath);
    if (!Array.isArray(rows)) fail(`${relativeSeedPath} must contain a JSON array`);
    rowsByEntity.set(entity.logicalName, rows);
  }
  return { manifest, rowsByEntity, schemaByEntity };
}

function seedValueIsCompatible(field, value, previousField, validIdsByEntity, entities) {
  if (value === null || value === undefined) return !field.required;
  if (previousField && previousField.type !== field.type) return false;
  if (field.type === 'number') return typeof value === 'number' && Number.isFinite(value);
  if (field.type === 'boolean') return typeof value === 'boolean';
  if (field.type === 'choice') {
    if (typeof value !== 'number' || !Number.isFinite(value)) return false;
    if (!field.options.length) return true;
    return field.options.some((option) => {
      const optionValue = typeof option === 'object' && option !== null ? option.value : option;
      return optionValue === value;
    });
  }
  if (field.type === 'lookup') {
    if (typeof value !== 'string') return false;
    const target = resolveLookupTarget(field, entities);
    return !target || (validIdsByEntity.get(target.logicalName) || new Set()).has(value);
  }
  return typeof value === 'string';
}

function isDerivedMediaField(field) {
  const semantic = `${field?.name || ''} ${field?.displayName || ''}`;
  return field?.type === 'image'
    || /(?:image|photo|media).*(?:url|alt|description|cache|asset|fallback|key)|(?:url|alt|description|cache|asset|fallback|key).*(?:image|photo|media)/i.test(semantic);
}

function mergeExistingSeeds(projectDir, entities, contextText, experienceContract, screenBuildPack = null) {
  const generatedRows = generateSeeds(entities, contextText, experienceContract, screenBuildPack);
  const previous = loadPreviousPrototype(projectDir, entities);
  const validIdsByEntity = new Map();

  for (const entity of entities) {
    const ids = new Set();
    for (const row of previous.rowsByEntity.get(entity.logicalName) || []) {
      if (typeof row?.[entity.primaryKey] === 'string') ids.add(row[entity.primaryKey]);
    }
    for (const row of generatedRows.get(entity.logicalName) || []) ids.add(row[entity.primaryKey]);
    validIdsByEntity.set(entity.logicalName, ids);
  }

  const rowsByEntity = new Map();
  const tableReports = [];
  for (const entity of [...entities].sort((left, right) => left.dependencyTier - right.dependencyTier)) {
    const existingRows = previous.rowsByEntity.get(entity.logicalName) || [];
    const baselineRows = generatedRows.get(entity.logicalName) || [];
    const previousSchema = previous.schemaByEntity.get(entity.logicalName);
    const previousFields = new Map(
      (previousSchema?.fields || []).map((field) => [field.name, field]),
    );
    const currentFields = new Set(entity.fields.map((field) => field.name));
    const addedFields = entity.fields
      .filter((field) => !previousFields.has(field.name))
      .map((field) => field.name);
    const removedFields = [...previousFields.keys()].filter((field) => !currentFields.has(field));
    const regeneratedFields = new Set();

    const mergedRows = existingRows.length
      ? existingRows.map((existingRow, index) => {
        const baseline = baselineRows[index % Math.max(1, baselineRows.length)] || {};
        const merged = {
          [entity.primaryKey]: typeof existingRow?.[entity.primaryKey] === 'string'
            ? existingRow[entity.primaryKey]
            : deterministicGuid(`${entity.logicalName}-${index}`),
        };
        for (const field of entity.fields) {
          if (field.name === entity.primaryKey) continue;
          const existingValue = existingRow?.[field.name];
          if (!isDerivedMediaField(field)
            && Object.prototype.hasOwnProperty.call(existingRow || {}, field.name)
            && seedValueIsCompatible(
              field,
              existingValue,
              previousFields.get(field.name),
              validIdsByEntity,
              entities,
            )) {
            merged[field.name] = existingValue;
          } else {
            merged[field.name] = baseline[field.name];
            if (Object.prototype.hasOwnProperty.call(existingRow || {}, field.name)
              && existingValue !== baseline[field.name]) {
              regeneratedFields.add(field.name);
            }
          }
        }
        return merged;
      })
      : baselineRows;

    rowsByEntity.set(entity.logicalName, mergedRows);
    tableReports.push({
      logicalName: entity.logicalName,
      rows: mergedRows.length,
      preservedRows: existingRows.length,
      addedFields,
      removedFields,
      regeneratedFields: [...regeneratedFields].sort(),
    });
  }

  return { rowsByEntity, previousManifest: previous.manifest, tableReports };
}

function archiveStaleGeneratedFiles(projectDir, previousManifest, generatedFiles) {
  if (!previousManifest || !Array.isArray(previousManifest.files)) return [];
  const generatedSet = new Set(generatedFiles);
  const removed = [];
  const archiveRoot = path.join(projectDir, '.tmp', 'prototype-seed-archive');

  for (const relativePath of previousManifest.files) {
    if (generatedSet.has(relativePath)) continue;
    const normalized = String(relativePath).split('\\').join('/');
    if (!normalized.startsWith('src/generated/')) continue;
    const filePath = path.join(projectDir, normalized);
    if (!fs.existsSync(filePath)) continue;
    if (normalized.endsWith('.seed.json')) {
      const archivePath = path.join(archiveRoot, normalized);
      fs.mkdirSync(path.dirname(archivePath), { recursive: true });
      fs.copyFileSync(filePath, archivePath);
      fs.rmSync(filePath, { force: true });
      removed.push({ file: normalized, archivedTo: path.relative(projectDir, archivePath).split(path.sep).join('/') });
      continue;
    }
    const contents = readOptional(filePath);
    if (contents.includes(GENERATOR_MARKER)) {
      fs.rmSync(filePath, { force: true });
      removed.push({ file: normalized, archivedTo: null });
    }
  }
  return removed;
}

function schemaType(field) {
  if (field.type === 'number' || field.type === 'choice') return 'number';
  if (field.type === 'boolean') return 'boolean';
  return 'string';
}

function renderSchema(entity) {
  const properties = [`  ${JSON.stringify(entity.primaryKey)}: string;`];
  for (const field of entity.fields) {
    if (field.name === entity.primaryKey) continue;
    properties.push(`  ${JSON.stringify(field.name)}${field.required ? '' : '?'}: ${schemaType(field)};`);
  }
  return `// ${GENERATOR_MARKER}\n// Prototype schema for ${entity.logicalName}; real generated models replace this during graduation.\nexport interface ${entity.serviceName} {\n${properties.join('\n')}\n}\n`;
}

function renderService(entity) {
  return `// ${GENERATOR_MARKER}\n// In-memory prototype service. State resets when the JavaScript bundle reloads.\nimport seedRows from './${entity.serviceName}.seed.json';\nimport type { ${entity.serviceName} } from '../schemas/${entity.serviceName}.Schema';\n\nlet rows: ${entity.serviceName}[] | null = null;\n\nfunction load(): ${entity.serviceName}[] {\n  if (rows === null) rows = JSON.parse(JSON.stringify(seedRows)) as ${entity.serviceName}[];\n  return rows;\n}\n\nfunction newId(): string {\n  return 'xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx'.replace(/x/g, () => Math.floor(Math.random() * 16).toString(16));\n}\n\nexport type ${entity.serviceName}GetAllOptions = {\n  orderBy?: string;\n  top?: number;\n};\n\nexport const ${entity.serviceName}Service = {\n  async getAll(options?: ${entity.serviceName}GetAllOptions): Promise<${entity.serviceName}[]> {\n    let result = [...load()];\n    if (options?.orderBy) {\n      const [field, direction = 'asc'] = options.orderBy.split(/\\s+/);\n      result.sort((left, right) => {\n        const a = (left as Record<string, unknown>)[field];\n        const b = (right as Record<string, unknown>)[field];\n        if (a === b) return 0;\n        const comparison = String(a).localeCompare(String(b), undefined, { numeric: true });\n        return direction.toLowerCase() === 'desc' ? -comparison : comparison;\n      });\n    }\n    return options?.top ? result.slice(0, options.top) : result;\n  },\n  async getById(id: string): Promise<${entity.serviceName} | undefined> {\n    return load().find((row) => row[${JSON.stringify(entity.primaryKey)}] === id);\n  },\n  async create(input: Omit<${entity.serviceName}, ${JSON.stringify(entity.primaryKey)}>): Promise<${entity.serviceName}> {\n    const created = { ...input, [${JSON.stringify(entity.primaryKey)}]: newId() } as ${entity.serviceName};\n    rows = [...load(), created];\n    return created;\n  },\n  async update(id: string, patch: Partial<${entity.serviceName}>): Promise<${entity.serviceName}> {\n    const currentRows = load();\n    const index = currentRows.findIndex((row) => row[${JSON.stringify(entity.primaryKey)}] === id);\n    if (index < 0) throw new Error('${entity.displayName} ' + id + ' not found');\n    currentRows[index] = { ...currentRows[index], ...patch };\n    return currentRows[index];\n  },\n  async delete(id: string): Promise<void> {\n    rows = load().filter((row) => row[${JSON.stringify(entity.primaryKey)}] !== id);\n  },\n  async clear(): Promise<void> {\n    rows = null;\n  },\n};\n\nexport default ${entity.serviceName}Service;\n`;
}

function renderConnectorStub(connector) {
  const message = `Connector "${connector.apiName}" (${connector.displayName}) is planned but unavailable in prototype mode. Run /prototype-to-real-app to provision it.`;
  const safePurpose = connector.purpose.replace(/\*\//g, '* /');
  const methods = (connector.operations || []).map((operation) => `  async ${operation}(..._args: unknown[]): Promise<never> {\n    throw new Error(MESSAGE);\n  },`).join('\n');
  if (methods) {
    return `// ${GENERATOR_MARKER}\n// Prototype-mode typed throw-stub for ${connector.displayName}.\n// Planned purpose: ${safePurpose}\nconst MESSAGE = ${JSON.stringify(message)};\n\nexport const ${connector.serviceName}Service = {\n${methods}\n};\n\nexport default ${connector.serviceName}Service;\n`;
  }
  return `// ${GENERATOR_MARKER}\n// Legacy prototype-mode throw-stub for ${connector.displayName}.\n// Planned purpose: ${safePurpose}\nconst MESSAGE = ${JSON.stringify(message)};\n\ntype ConnectorStub = Record<string, (...args: unknown[]) => Promise<unknown>>;\n\nexport const ${connector.serviceName}Service: ConnectorStub = new Proxy({} as ConnectorStub, {\n  get(_target, property: string | symbol) {\n    if (typeof property === 'symbol' || property === 'then' || property === 'toJSON') return undefined;\n    return (..._args: unknown[]) => Promise.reject(new Error(MESSAGE));\n  },\n});\n\nexport default ${connector.serviceName}Service;\n`;
}

function renderOperationService(entity) {
  return `// ${GENERATOR_MARKER}\n// In-memory prototype service with the same result envelope and query surface as generated table services.\nimport seedRows from './${entity.serviceName}.seed.json';\nimport type { ${entity.serviceName} } from '../schemas/${entity.serviceName}.Schema';\n\nlet rows: ${entity.serviceName}[] | null = null;\n\nfunction load(): ${entity.serviceName}[] {\n  if (rows === null) rows = JSON.parse(JSON.stringify(seedRows)) as ${entity.serviceName}[];\n  return rows;\n}\n\nfunction newId(): string {\n  return 'xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx'.replace(/x/g, () => Math.floor(Math.random() * 16).toString(16));\n}\n\nfunction filterRows(values: ${entity.serviceName}[], filter?: string): ${entity.serviceName}[] {\n  if (!filter) return values;\n  const clauses = filter.split(/\\s+and\\s+/i);\n  return values.filter((row) => clauses.every((clause) => {\n    const contains = clause.match(/^contains\\(([^,]+),\\s*'((?:''|[^'])*)'\\)$/i);\n    if (contains) return String(Reflect.get(row, contains[1].trim()) ?? '').toLowerCase().includes(contains[2].replace(/''/g, "'").toLowerCase());\n    const equality = clause.match(/^([A-Za-z_$][\\w$]*)\\s+eq\\s+(?:'((?:''|[^'])*)'|(true|false|-?\\d+(?:\\.\\d+)?))$/i);\n    if (!equality) return true;\n    const raw = equality[2] !== undefined ? equality[2].replace(/''/g, "'") : equality[3];\n    const expected = /^(?:true|false)$/i.test(raw) ? raw.toLowerCase() === 'true' : /^-?\\d+(?:\\.\\d+)?$/.test(raw) ? Number(raw) : raw;\n    return Reflect.get(row, equality[1]) === expected;\n  }));\n}\n\nexport type ${entity.serviceName}GetAllOptions = {\n  filter?: string;\n  maxPageSize?: number;\n  orderBy?: string | string[];\n  select?: string[];\n  skipToken?: string;\n  top?: number;\n};\n\nexport type ${entity.serviceName}Result<T> = { data: T; error?: never; skipToken?: string };\n\nexport const ${entity.serviceName}Service = {\n  async getAll(options?: ${entity.serviceName}GetAllOptions): Promise<${entity.serviceName}Result<${entity.serviceName}[]>> {\n    let result = filterRows([...load()], options?.filter);\n    const orderBy = typeof options?.orderBy === 'string' ? [options.orderBy] : options?.orderBy || [];\n    for (const order of [...orderBy].reverse()) {\n      const [field, direction = 'asc'] = order.split(/\\s+/);\n      result.sort((left, right) => {\n        const leftValue = Reflect.get(left, field);\n        const rightValue = Reflect.get(right, field);\n        if (leftValue === rightValue) return 0;\n        const comparison = String(leftValue).localeCompare(String(rightValue), undefined, { numeric: true });\n        return direction.toLowerCase() === 'desc' ? -comparison : comparison;\n      });\n    }\n    const start = Math.max(0, Number.parseInt(options?.skipToken || '0', 10) || 0);\n    const pageSize = Math.max(1, options?.maxPageSize || options?.top || result.length || 1);\n    const data = result.slice(start, start + pageSize);\n    const next = start + data.length;\n    return { data, ...(next < result.length ? { skipToken: String(next) } : {}) };\n  },\n  async get(id: string): Promise<${entity.serviceName}Result<${entity.serviceName} | undefined>> {\n    return { data: load().find((row) => row[${JSON.stringify(entity.primaryKey)}] === id) };\n  },\n  async getById(id: string): Promise<${entity.serviceName} | undefined> {\n    return load().find((row) => row[${JSON.stringify(entity.primaryKey)}] === id);\n  },\n  async create(input: Omit<${entity.serviceName}, ${JSON.stringify(entity.primaryKey)}>): Promise<${entity.serviceName}Result<${entity.serviceName}>> {\n    const created = { ...input, [${JSON.stringify(entity.primaryKey)}]: newId() } as ${entity.serviceName};\n    rows = [...load(), created];\n    return { data: created };\n  },\n  async update(id: string, patch: Partial<${entity.serviceName}>): Promise<${entity.serviceName}Result<${entity.serviceName}>> {\n    const currentRows = load();\n    const index = currentRows.findIndex((row) => row[${JSON.stringify(entity.primaryKey)}] === id);\n    if (index < 0) throw new Error('${entity.displayName} ' + id + ' not found');\n    currentRows[index] = { ...currentRows[index], ...patch };\n    return { data: currentRows[index] };\n  },\n  async delete(id: string): Promise<${entity.serviceName}Result<null>> {\n    rows = load().filter((row) => row[${JSON.stringify(entity.primaryKey)}] !== id);\n    return { data: null };\n  },\n  async clear(): Promise<void> {\n    rows = null;\n  },\n};\n\nexport default ${entity.serviceName}Service;\n`;
}

function renderStrictService(entity) {
  // Generated row schemas are interfaces without index signatures. Reflect.get
  // keeps user-selected orderBy fields strict-mode compatible without emitting
  // a broad Record assertion into every generated service.
  return renderOperationService(entity);
}

function renderDataSourcesInfo(entities, connectors) {
  const serviceExports = entities.map((entity) => `export { ${entity.serviceName}Service } from './${entity.serviceName}Service';`);
  const typeExports = entities.map((entity) => `export type { ${entity.serviceName} } from '../schemas/${entity.serviceName}.Schema';`);
  const connectorExports = connectors.map((connector) => `export { ${connector.serviceName}Service } from './${connector.serviceName}Service';`);
  return `// ${GENERATOR_MARKER}\n${[...serviceExports, ...connectorExports, '', ...typeExports].join('\n')}\n\nexport const REGISTERED_DATA_SOURCES = ${JSON.stringify(entities.map((entity) => entity.logicalName), null, 2)} as const;\nexport const REGISTERED_CONNECTORS = ${JSON.stringify(connectors.map((connector) => connector.apiName), null, 2)} as const;\n`;
}

function writeGeneratedFile(projectDir, relativePath, content, generatedFiles) {
  const filePath = path.join(projectDir, relativePath);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content);
  generatedFiles.push(relativePath.split(path.sep).join('/'));
}

function main() {
  const projectArg = process.argv[2];
  if (!projectArg) fail('usage: node gen-mock-services.js <project-dir>');
  const projectDir = path.resolve(projectArg);
  const planPath = path.join(projectDir, 'native-app-plan.md');
  if (!fs.existsSync(projectDir)) fail(`project directory not found: ${projectDir}`);
  if (!fs.existsSync(planPath)) fail(`native-app-plan.md not found under ${projectDir}`);

  const planText = fs.readFileSync(planPath, 'utf8');
  const briefText = readOptional(path.join(projectDir, 'brief.md'));
  const screenBuildPack = loadScreenBuildPack(projectDir);
  const experienceContract = screenBuildPack ? screenBuildPack.experience : loadExperienceContract(projectDir);
  if (!screenBuildPack) {
    console.warn('prototype-mocks: compatibility fallback: screen build pack unavailable; using experience contract directly.');
  }
  const { entities, source } = loadEntities(projectDir, planText);
  const connectors = connectorsFromExecutionContract(projectDir) || parseConnectors(planText);
  const duplicate = entities.find((entity, index) => entities.findIndex((candidate) => candidate.logicalName === entity.logicalName) !== index);
  if (duplicate) fail(`duplicate table logicalName in schema contract: ${duplicate.logicalName}`);

  const seedMerge = mergeExistingSeeds(
    projectDir,
    entities,
    screenBuildPack ? JSON.stringify(screenBuildPack.fixtures) : `${briefText}\n${planText}`,
    experienceContract,
    screenBuildPack,
  );
  const rowsByEntity = seedMerge.rowsByEntity;
  const generatedFiles = [];
  const assetManifestPath = 'assets/experience/manifest.json';
  const assetManifest = buildExperienceAssetManifest(entities, rowsByEntity, experienceContract);
  const materializedMedia = materializeExperienceAssets(projectDir, assetManifest);
  const viewModel = buildExperienceViewModel(entities, rowsByEntity, assetManifestPath, assetManifest);
  const fixtureScenariosPath = 'src/generated/fixture-scenarios.json';
  const fixtureScenarios = buildFixtureScenarioManifest(screenBuildPack, entities, rowsByEntity, assetManifest);
  generatedFiles.push(...materializedMedia.files);
  writeGeneratedFile(projectDir, assetManifestPath, `${JSON.stringify(assetManifest, null, 2)}\n`, generatedFiles);
  writeGeneratedFile(projectDir, 'src/generated/experience-view-model.ts', renderExperienceViewModel(viewModel), generatedFiles);
  writeGeneratedFile(projectDir, fixtureScenariosPath, `${JSON.stringify(fixtureScenarios, null, 2)}\n`, generatedFiles);
  for (const entity of entities) {
    writeGeneratedFile(projectDir, `src/generated/services/${entity.serviceName}Service.ts`, renderStrictService(entity), generatedFiles);
    writeGeneratedFile(projectDir, `src/generated/services/${entity.serviceName}.seed.json`, `${JSON.stringify(rowsByEntity.get(entity.logicalName), null, 2)}\n`, generatedFiles);
    writeGeneratedFile(projectDir, `src/generated/schemas/${entity.serviceName}.Schema.ts`, renderSchema(entity), generatedFiles);
  }
  for (const connector of connectors) {
    writeGeneratedFile(projectDir, `src/generated/services/${connector.serviceName}Service.ts`, renderConnectorStub(connector), generatedFiles);
  }
  writeGeneratedFile(projectDir, 'src/generated/services/dataSourcesInfo.ts', renderDataSourcesInfo(entities, connectors), generatedFiles);
  writeGeneratedFile(projectDir, 'src/generated/services/index.ts', "// Generated by create-mobile-prototype/gen-mock-services.js\nexport * from './dataSourcesInfo';\n", generatedFiles);
  writeGeneratedFile(projectDir, 'src/generated/index.ts', "// Generated by create-mobile-prototype/gen-mock-services.js\nexport * from './services';\n", generatedFiles);

  const removedGeneratedFiles = archiveStaleGeneratedFiles(
    projectDir,
    seedMerge.previousManifest,
    generatedFiles,
  );

  const regenerationReportPath = path.join(projectDir, '.tmp', 'prototype-seed-regeneration.json');
  fs.mkdirSync(path.dirname(regenerationReportPath), { recursive: true });
  fs.writeFileSync(regenerationReportPath, `${JSON.stringify({
    schemaVersion: 1,
    experienceContract: experienceContract ? {
      audience: experienceContract.audience,
      primaryJob: experienceContract.primaryJob,
      interactionMode: experienceContract.interactionMode,
      entryMode: experienceContract.entryMode,
      contentModel: experienceContract.contentModel,
    } : null,
    screenBuildPackRevision: screenBuildPack?.revision || null,
    assetManifest: assetManifestPath,
    viewModel: 'src/generated/experience-view-model.ts',
    fixtureScenarios: fixtureScenariosPath,
    tables: seedMerge.tableReports,
    removedGeneratedFiles,
  }, null, 2)}\n`);

  const manifestPath = path.join(projectDir, 'src', 'generated', '.prototype-manifest.json');
  fs.mkdirSync(path.dirname(manifestPath), { recursive: true });
  fs.writeFileSync(manifestPath, `${JSON.stringify({
    schemaVersion: 1,
    generator: 'create-mobile-prototype/gen-mock-services.js',
    schemaSource: source,
    experienceContractSource: screenBuildPack ? '.tmp/screen-build-pack.json#experience' : experienceContract ? '.tmp/experience-contract.json' : null,
    screenBuildPackRevision: screenBuildPack?.revision || null,
    assetManifest: assetManifestPath,
    viewModel: 'src/generated/experience-view-model.ts',
    fixtureScenarios: fixtureScenariosPath,
    tables: entities.map((entity) => entity.logicalName),
    tableSchemas: entities.map((entity) => ({
      logicalName: entity.logicalName,
      displayName: entity.displayName,
      serviceName: entity.serviceName,
      seedFile: `src/generated/services/${entity.serviceName}.seed.json`,
      primaryKey: entity.primaryKey,
      dependencyTier: entity.dependencyTier,
      fields: entity.fields.map((field) => ({
        name: field.name,
        type: field.type,
        required: field.required,
        lookupTarget: field.lookupTarget,
        options: field.options,
      })),
    })),
    connectors: connectors.map((connector) => connector.apiName),
    files: generatedFiles,
    seedRegenerationReport: '.tmp/prototype-seed-regeneration.json',
  }, null, 2)}\n`);

  console.log(`prototype-mocks: generated ${entities.length} table service(s) and ${connectors.length} connector stub(s)`);
  console.log(`prototype-mocks: schema source ${source}`);
}

if (require.main === module) main();

module.exports = {
  buildFixturePolicy,
  buildFixtureScenarioManifest,
  domainPack,
  experiencePack,
  fixtureScenarioInputs,
  generateSeeds,
  loadExperienceContract,
  loadScreenBuildPack,
};
